]$selective_tools_patches$::jsonb;
 method text:=$selective_construction_method$ Choose the smallest work unit: existing numeric inputs use change_construction_parameters, role-only edits use change_construction_roles, and changed parts/dependencies use edit_construction_parts. Do not split a small furniture correction into separate drawing jobs. For a larger new build, establish a shared origin, axes, interface dimensions and exact source revisions; work on one natural sub-construction at a time and save/check its receipt before starting the next. Carry the common interface and exact receipts, not every other piece’s raw graph. Reopen only relevant revision-bound views when an interface changes. For evenly spaced identical parts, use recipe.arrays in save_construction_draft; code expands and validates all placements and source-linked formulas. Roles and joints still name individual expanded IDs. Once all pieces are checked, load plan_cad_pieces and queue their exact revisions with the common assembly brief plus each piece’s own requirements/source references. The queue renders saved canonical geometry; it does not design it. Keep uncertain interfaces explicit and resolve them before claiming an assembled fit.$selective_construction_method$;
 patch jsonb; prior shared.ai_prompt_versions; next_version integer; version_uuid uuid; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 if not exists(select 1 from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.read_construction_draft' and v.metadata->>'construction_view_version'='1') then raise exception 'construction_views_publication_required'; end if;
 for patch in select value from jsonb_array_elements(patches) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=patch->>'key' for update of p;
  if not found then raise exception 'selective_tools_dependency_missing'; end if;
  definition:=prior.definition||(patch->'definition');
  if patch->>'key'='bob.workflows' then
   definition:=jsonb_set(definition,'{workflows}',(select jsonb_agg(case when w->>'name'='workflow_construction_drawing' then jsonb_set(jsonb_set(w,'{method}',to_jsonb((w->>'method')||method)),'{tools}',(w->'tools')||'["plan_cad_pieces"]'::jsonb) else w end order by n) from jsonb_array_elements(definition->'workflows') with ordinality x(w,n)));
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','selective-tools-v1')||(patch->'metadata'),coalesce(patch->>'content',prior.content),definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 perform shared.activate_ai_catalog('bob',activation);
end $selective_tools_publication$;
commit;
